import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"MCP server","description":"tuimark mcp (0.3b) - a Model Context Protocol server that gives a coding agent the validate/dump/play authoring loop as five tools, over stdin/stdout.","frontmatter":{"title":"MCP server","description":"tuimark mcp (0.3b) - a Model Context Protocol server that gives a coding agent the validate/dump/play authoring loop as five tools, over stdin/stdout.","head":[["link",{"rel":"canonical","href":"https://tuimark.vercel.app/guide/mcp"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Tuimark"}],["meta",{"property":"og:title","content":"MCP server | Tuimark"}],["meta",{"property":"og:description","content":"tuimark mcp (0.3b) - a Model Context Protocol server that gives a coding agent the validate/dump/play authoring loop as five tools, over stdin/stdout."}],["meta",{"property":"og:url","content":"https://tuimark.vercel.app/guide/mcp"}],["meta",{"name":"twitter:title","content":"MCP server | Tuimark"}],["meta",{"name":"twitter:description","content":"tuimark mcp (0.3b) - a Model Context Protocol server that gives a coding agent the validate/dump/play authoring loop as five tools, over stdin/stdout."}]]},"headers":[],"relativePath":"guide/mcp.md","filePath":"guide/mcp.md","lastUpdated":1790601904000}'),s={name:"guide/mcp.md"};function i(r,e,c,n,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="mcp-server" tabindex="-1">MCP server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP server&quot;">​</a></h1><p><code>tuimark mcp</code> (0.3b) is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server on stdin/stdout. It gives a coding agent the same <a href="/guide/agents#the-loop">authoring loop</a> — <code>validate</code>, <code>dump</code>, <code>play</code>, plus <code>inspect</code> and the <code>AGENTS.md</code> briefing — as tool calls, for an agent that reaches Tuimark through an MCP gateway rather than a shell. It is standard library only, JSON-RPC 2.0, one message per line, and every result is exactly what the matching CLI command would print to stdout, byte for byte.</p><p>If your agent already has a shell, the <a href="/guide/tools">CLI</a> and this server do the same work; use whichever your environment gives you. They agree by construction — every tool call runs the same code path as its CLI command.</p><h2 id="registering-it" tabindex="-1">Registering it <a class="header-anchor" href="#registering-it" aria-label="Permalink to &quot;Registering it&quot;">​</a></h2><p>Point your MCP client at the <code>tuimark</code> binary with the <code>mcp</code> subcommand and no other arguments:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tuimark&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tuimark&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The exact place this JSON goes depends on your client (a project config file, a global settings file, or a CLI flag); consult its docs for &quot;MCP server&quot; or &quot;stdio server&quot; configuration. The server reads no environment variable and needs no other setup — just a <code>tuimark</code> binary on <code>PATH</code> (or an absolute <code>command</code>).</p><h2 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;The tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Required</th><th>Optional</th><th>Runs</th></tr></thead><tbody><tr><td><code>tuimark_validate</code></td><td><code>file</code></td><td><code>data</code>, <code>theme</code>, <code>strict</code>, <code>catalog</code></td><td><code>tuimark validate FILE --json</code></td></tr><tr><td><code>tuimark_dump</code></td><td><code>file</code></td><td><code>data</code>, <code>cols</code>, <code>rows</code>, <code>theme</code>, <code>styles</code>, <code>cells</code>, <code>strict</code></td><td><code>tuimark dump FILE --format json</code></td></tr><tr><td><code>tuimark_play</code></td><td><code>file</code></td><td><code>steps</code>, <code>data</code>, <code>cols</code>, <code>rows</code>, <code>theme</code>, <code>styles</code>, <code>cells</code>, <code>frames</code>, <code>strict</code></td><td><code>tuimark play FILE --format json</code></td></tr><tr><td><code>tuimark_inspect</code></td><td><code>file</code></td><td><code>at</code>, <code>id</code>, <code>data</code>, <code>cols</code>, <code>rows</code>, <code>theme</code>, <code>strict</code></td><td><code>tuimark inspect FILE --json</code></td></tr><tr><td><code>tuimark_agents</code></td><td>—</td><td>—</td><td><code>tuimark agents</code></td></tr></tbody></table><p>The list is closed and matches the <a href="/guide/agents#the-loop">loop</a> on purpose: <code>fmt</code> and <code>test</code> are left out because they can write files, which this read-only server never does; <code>ir</code>, <code>preview</code>, <code>host</code>, and <code>version</code> are left out because they serve runtime debugging, a terminal, or a version string, not authoring.</p><p>Every tool argument maps to the flag of the same name (<code>data</code> → <code>--data</code>, <code>theme</code> → <code>--theme</code>, and so on); <code>strict</code>, <code>styles</code>, <code>cells</code>, and <code>frames</code> become the bare flag when <code>true</code> and nothing when <code>false</code>. <code>cols</code> and <code>rows</code> take any JSON number without a fraction (<code>1e3</code> is <code>1000</code>, <code>1.0</code> is <code>1</code>), and their exact digits reach <code>--cols</code>/<code>--rows</code>, so a value out of range gets the CLI&#39;s own message for those digits. The <code>file</code>, like every other argument, goes through the command&#39;s own flag parsing, so the result is what the command line above prints for it. <code>steps</code> (default: none, step 0 only) is an array of strings, one <a href="/guide/tools#play"><code>play</code> step</a> each, and — unlike <code>--input</code> on the command line — a step in the array may contain spaces (<code>&quot;text:hello world&quot;</code>), since there is no shell splitting to worry about.</p><p>Every tool is marked <code>readOnlyHint: true</code>, and none of them writes a file or keeps state between calls: each call loads its document fresh.</p><h2 id="reading-a-result" tabindex="-1">Reading a result <a class="header-anchor" href="#reading-a-result" aria-label="Permalink to &quot;Reading a result&quot;">​</a></h2><ul><li>When the underlying command would exit <code>0</code> (clean) or <code>2</code> (validation errors — data, not failure), the tool result is <strong>not</strong> an error, and its text is the command&#39;s stdout: the same JSON <code>tuimark dump --format json</code> would print, for instance, <code>&quot;ok&quot;: false</code> included when there were diagnostics. Read <code>errors</code>/<code>ok</code> in the JSON to see the problems, the same way you would from the CLI.</li><li>When the command would exit <code>1</code> (a missing file, a bad flag value), the result has <code>isError: true</code>, and its text is the command&#39;s stderr line, such as <code>tuimark: open nope.tui: no such file or directory</code>.</li><li><strong>Argument errors</strong> — a required argument missing, an argument the tool does not take, or a value of the wrong JSON type — are also <code>isError</code> results, checked before the command runs, so a mistake in the call never starts the CLI: <code>tuimark: missing argument &quot;file&quot;</code>, <code>tuimark: unknown argument &quot;input&quot;</code> (the CLI&#39;s flag name for <code>steps</code>, a common slip), <code>tuimark: cols: want integer</code>.</li></ul><p>An agent following the <a href="/guide/agents#the-loop">authoring loop</a> reads these the same way it reads CLI output: fix every error <code>validate</code> reports, check the <code>dump</code> at 80 and 120 columns, and confirm the right action fired with <code>play</code>.</p><h2 id="protocol-notes" tabindex="-1">Protocol notes <a class="header-anchor" href="#protocol-notes" aria-label="Permalink to &quot;Protocol notes&quot;">​</a></h2><ul><li><code>initialize</code> answers with <code>protocolVersion</code> set to whichever of <code>2025-11-25</code>, <code>2025-06-18</code>, <code>2025-03-26</code>, or <code>2024-11-05</code> the client asked for (else <code>2025-11-25</code>), and <code>serverInfo.name</code> is <code>&quot;tuimark&quot;</code> with the bare runtime version. It never fails because of the version.</li><li><code>tools/list</code> returns all five tools with no pagination; <code>ping</code> answers <code>{}</code>.</li><li>The server exits <code>0</code> when stdin reaches end of file, and <code>1</code> if reading stdin or writing stdout fails.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/agents">Working with agents</a> — the authoring loop this server exposes as tools, and how to read a dump.</li><li><a href="/guide/tools">Dumps and tools</a> — the same commands from a shell.</li><li><a href="/guide/host-protocol">Host protocol</a> — for driving a <em>live</em> session, not the authoring loop.</li></ul>`,19)])])}const m=o(s,[["render",i]]);export{p as __pageData,m as default};
